const state={source:null,raw:[],all:null,filtered:[],result:null,filters:{region:null,name:null,type:null,year:null,from:null,to:null},tab:'apartments',caseResult:null,sort:{},order:{},selected:{},query:'',busy:false};
let activeFilter=null,loadToken=0;
const filterDefs=[{key:'region',label:'동',get:r=>r.regionKey},{key:'name',label:'단지',get:r=>r.name},{key:'type',label:'타입',get:r=>Number.isFinite(r.type)&&r.area>0?String(r.type):null},{key:'year',label:'건축년도',get:r=>r.year}];
function notify(message,error=false){$('#message').textContent=message;$('#message').classList.toggle('error',error);}
function busy(on){state.busy=on;document.body.classList.toggle('busy',on);$('#filters').disabled=on||!state.source;$('#openFile').disabled=on;$('#emptyOpen').disabled=on;$('#export').disabled=on||!state.source;$('#copySelected').disabled=on;$('#copyAll').disabled=on;$('#analyzeCase').disabled=on||!state.source;$('#search').disabled=state.tab==='cases';}
async function loadFile(file){if(!file||state.busy)return;const token=++loadToken;busy(true);closeFilter();try{const source=await readXlsx(file,msg=>notify(msg));const rows=E.parseRows(source);const all=E.aggregate(rows);if(token!==loadToken)return;state.source=source;state.raw=rows;state.all={...all,raw:rows};state.filters={region:null,name:null,type:null,year:null,from:null,to:null};state.query='';state.sort={};state.selected={};state.caseResult=null;$('#search').value='';setDateInputs();renderFilters();applyFilters();$('#fileName').textContent=file.name+' · '+source.sheetName;$('#source').textContent=E.sourceText(source);$('#loadedInfo').hidden=false;$('#empty').hidden=true;$('#results').hidden=false;notify(`${nf.format(rows.length)}건을 읽었습니다. 분석에 포함된 거래는 ${nf.format(all.included.length)}건입니다.`);}catch(err){notify(err.message||'파일을 읽지 못했습니다.',true);}finally{busy(false);$('#file').value='';}}
function setDateInputs(){const dates=state.raw.map(r=>r.date).filter(Boolean).sort();$('#from').value=dates[0]||'';$('#to').value=dates.at(-1)||'';}
function applyFilters(){if(!state.source)return;state.filtered=E.filtered(state.raw,state.filters);state.result=E.aggregate(state.filtered);state.selected={};const r=state.result;$('#stats').replaceChildren();for(const [label,value,cls] of [['원본',state.raw.length,''],['포함',r.included.length,'included'],['제외',r.excluded.length,''],['단지·타입',r.apartments.length,'']]){const box=el('div','stat '+cls);box.append(el('span','',label),el('strong','',nf.format(value)));$('#stats').append(box);}$('#dateBasis').textContent=state.filters.from?`적용 중: ${state.filters.from} ~ ${state.filters.to} · 양 끝 날짜 포함`:'전체 기간 · 시작일과 종료일 포함';$('#exclusionSummary').textContent='선택 조건 제외: '+(Object.entries(r.reasons).map(([k,v])=>`${k} ${nf.format(v)}건`).join(' · ')||'없음');populateCaseProperties();renderTable();}
function resetAll(){if(!state.source)return;state.filters={region:null,name:null,type:null,year:null,from:null,to:null};state.query='';$('#search').value='';setDateInputs();renderFilters();applyFilters();}
function filterChoices(def){return [...new Set(state.raw.map(def.get).filter(v=>v!=null&&v!==''))].sort(def.key==='type'?(a,b)=>+a-+b:(a,b)=>a.localeCompare(b,'ko',{numeric:true}));}
function renderFilters(){$('#filterButtons').replaceChildren();for(const def of filterDefs){const wrap=el('div','filter'),button=el('button','filter-trigger');button.type='button';button.dataset.filter=def.key;button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-expanded','false');const values=state.filters[def.key];button.textContent=def.label+' · '+(values==null?'전체':values.size===0?'선택 없음':values.size===1?[...values][0]+(def.key==='type'?'타입':''):values.size+'개')+' ▾';button.classList.toggle('active',values!==null);button.addEventListener('click',()=>openFilter(def,wrap,button));wrap.append(button);$('#filterButtons').append(wrap);}}
function closeFilter(restoreFocus=false){if(activeFilter){activeFilter.button.setAttribute('aria-expanded','false');activeFilter.menu.remove();if(restoreFocus)activeFilter.button.focus();activeFilter=null;}}
function openFilter(def,wrap,button){if(activeFilter?.button===button){closeFilter(true);return;}closeFilter();const choices=filterChoices(def),pending=new Set(state.filters[def.key]??choices);const menu=el('div','filter-menu');menu.setAttribute('role','dialog');menu.setAttribute('aria-label',def.label+' 필터');const search=el('input');search.type='search';search.placeholder=def.label+' 검색';search.setAttribute('aria-label',def.label+' 목록 검색');const list=el('div','filter-options'),actions=el('div','filter-actions');let shown=[];
 const render=()=>{list.replaceChildren();const q=search.value.trim().toLowerCase();shown=choices.filter(v=>(v+(def.key==='type'?'타입':'')).toLowerCase().includes(q));
  const addOption=(text,keys,isGroup=false)=>{const label=el('label','option'+(isGroup?' group':'')),input=el('input');input.type='checkbox';const count=keys.filter(k=>pending.has(k)).length;input.checked=count===keys.length;input.indeterminate=count>0&&count<keys.length;input.addEventListener('change',()=>{for(const key of keys)input.checked?pending.add(key):pending.delete(key);render();});label.append(input,document.createTextNode(text));list.append(label);};
  if(def.key==='type'){const bands=[...new Set(choices.map(v=>Math.floor(+v/10)*10))];for(const band of bands){const keys=choices.filter(v=>+v>=band&&+v<band+10);if(q&&`${band}대타입`.includes(q))shown=[...new Set([...shown,...keys])];if(!q||`${band}대타입`.includes(q)||keys.some(k=>shown.includes(k))){addOption(`${band}대타입 (${band}~${band+9})`,keys,true);for(const key of keys)if(!q||shown.includes(key)||`${band}대타입`.includes(q))addOption(key+'타입',[key]);}}}else for(const choice of shown)addOption(choice,[choice]);if(!list.childElementCount)list.append(el('p','hint','일치하는 항목이 없습니다.'));};
 for(const [label,cls,action] of [['전체 선택','',()=>{shown.forEach(v=>pending.add(v));render();}],['전체 해제','',()=>{shown.forEach(v=>pending.delete(v));render();}],['확인','primary',()=>{state.filters[def.key]=pending.size===choices.length?null:new Set(pending);closeFilter();renderFilters();applyFilters();$(`[data-filter="${def.key}"]`)?.focus();}],['취소','',()=>closeFilter(true)]]){const b=el('button',cls,label);b.type='button';b.addEventListener('click',action);actions.append(b);}search.addEventListener('input',render);menu.append(search,list,actions);wrap.append(menu);activeFilter={menu,button};button.setAttribute('aria-expanded','true');render();const box=menu.getBoundingClientRect();if(box.right>innerWidth-12)menu.style.left=Math.min(0,innerWidth-12-box.right)+'px';search.focus();}
document.addEventListener('pointerdown',e=>{if(activeFilter&&!activeFilter.menu.contains(e.target)&&e.target!==activeFilter.button)closeFilter();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeFilter(true);if(e.key==='Tab'&&activeFilter){const focusable=[...activeFilter.menu.querySelectorAll('button,input')].filter(e=>!e.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function currentColumns(){const defs=COLUMNS[state.tab],order=state.order[state.tab];return order?order.map(k=>defs.find(c=>c.key===k)).filter(Boolean):defs;}
function currentRows(){if(!state.result)return [];let rows=state.tab==='cases'?(state.caseResult?.trades||[]):state.result[state.tab];if(state.tab!=='cases'&&state.query){const q=state.query.toLocaleLowerCase();rows=rows.filter(r=>COLUMNS[state.tab].some(c=>String(c.value(r)??'').toLocaleLowerCase().includes(q)));}const sorting=state.sort[state.tab];if(sorting){const c=COLUMNS[state.tab].find(c=>c.key===sorting.key),get=c.sort||c.value;rows=[...rows].sort((a,b)=>{const av=get(a),bv=get(b);let order;if(typeof av==='number'&&typeof bv==='number')order=(Number.isNaN(av)?Infinity:av)-(Number.isNaN(bv)?Infinity:bv);else order=String(av??'').localeCompare(String(bv??''),'ko',{numeric:true});if(!order&&c.tie)order=c.tie(a)-c.tie(b);return order*sorting.direction;});}return rows;}
function selectedSet(){return state.selected[state.tab]??(state.selected[state.tab]=new Set());}
function formatValue(value,c){return value==null?'':c.numeric&&typeof value==='number'?nf.format(value):String(value);}
function renderTable(){const table=$('#dataTable'),head=table.tHead,body=table.tBodies[0],columns=currentColumns(),rows=currentRows(),selected=selectedSet();table.style.width=(52+columns.reduce((sum,c)=>sum+(c.width||90),0))+'px';head.replaceChildren();body.replaceChildren();const tr=el('tr'),th=el('th','select-col'),all=el('input');all.type='checkbox';all.setAttribute('aria-label','현재 필터 결과 전체 행 선택');all.disabled=!rows.length;const checked=rows.filter(r=>selected.has(r.id)).length;all.checked=!!rows.length&&checked===rows.length;all.indeterminate=checked>0&&checked<rows.length;all.addEventListener('change',()=>{for(const r of rows)all.checked?selected.add(r.id):selected.delete(r.id);renderTable();});th.append(all);tr.append(th);
 for(const c of columns){const h=el('th',c.numeric?'numeric':'');h.scope='col';h.style.width=(c.width||90)+'px';h.dataset.key=c.key;h.draggable=true;const sorted=state.sort[state.tab]?.key===c.key?state.sort[state.tab].direction:0;h.setAttribute('aria-sort',sorted===1?'ascending':sorted===-1?'descending':'none');const b=el('button','',c.label);b.append(el('span','sort-arrow',sorted===1?'↑':sorted===-1?'↓':'↕'));b.addEventListener('click',()=>{state.sort[state.tab]={key:c.key,direction:sorted===1?-1:1};renderTable();});h.append(b);h.addEventListener('dragstart',e=>e.dataTransfer.setData('text/column',c.key));h.addEventListener('dragover',e=>{if([...e.dataTransfer.types].includes('text/column'))e.preventDefault();});h.addEventListener('drop',e=>{const from=e.dataTransfer.getData('text/column');if(!from)return;e.preventDefault();e.stopPropagation();const keys=currentColumns().map(c=>c.key),at=keys.indexOf(from);if(at<0)return;keys.splice(at,1);keys.splice(keys.indexOf(c.key),0,from);state.order[state.tab]=keys;renderTable();});tr.append(h);}head.append(tr);
 for(const r of rows){const line=el('tr',r.total?'total':'');line.classList.toggle('selected',selected.has(r.id));const cell=el('td','select-col'),box=el('input');box.type='checkbox';box.checked=selected.has(r.id);box.setAttribute('aria-label',`${r.name||r.date||''} 행 선택`);box.addEventListener('change',()=>{box.checked?selected.add(r.id):selected.delete(r.id);line.classList.toggle('selected',box.checked);updateTableInfo();const n=currentRows().filter(r=>selected.has(r.id)).length;all.checked=n===rows.length;all.indeterminate=n>0&&n<rows.length;});cell.append(box);line.append(cell);
  for(const c of columns){const td=el('td',c.numeric?'numeric':'');const text=formatValue(c.value(r),c);td.textContent=text;td.title=text;td.tabIndex=0;td.addEventListener('dblclick',()=>textEditor(td,text));td.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key==='F2'){e.preventDefault();textEditor(td,text);}});line.append(td);}body.append(line);}
 $('#noRows').hidden=rows.length>0;updateTableInfo();}
function updateTableInfo(){const rows=currentRows(),count=rows.filter(r=>selectedSet().has(r.id)).length;$('#tableInfo').textContent=`${nf.format(rows.length)}행 · 체크 ${nf.format(count)}행`+(state.tab==='cases'?' · 개별 거래내역':' · 검색은 표시 행만 제한');}
function textEditor(td,text){if(td.querySelector('input'))return;const input=el('input','text-editor');input.readOnly=true;input.value=text;input.setAttribute('aria-label','텍스트 선택 후 복사');td.replaceChildren(input);input.focus();input.select();const close=()=>{td.textContent=text;};input.addEventListener('blur',close,{once:true});input.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Escape'||e.key==='Enter'){close();td.focus();}});}
function setTab(tab){if(!COLUMNS[tab])throw Error('지원하지 않는 탭입니다.');closeFilter();state.tab=tab;for(const b of $$('.tabs button')){const on=b.dataset.tab===tab;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;}$('#results').setAttribute('aria-labelledby','tab-'+tab);$('#caseTools').hidden=tab!=='cases';$('#search').disabled=tab==='cases';$('#search').placeholder=tab==='cases'?'개별 사례는 아래에서 선택':'단지·주소 검색';renderTable();}
for(const b of $$('.tabs button')){b.addEventListener('click',()=>setTab(b.dataset.tab));b.addEventListener('keydown',e=>{const tabs=$$('.tabs button');if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const i=tabs.indexOf(b);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();setTab(tabs[next].dataset.tab);}});}
function populateCaseProperties(){const select=$('#caseProperty'),old=select.value;select.replaceChildren();const unique=new Map();for(const t of state.result.included)unique.set(E.propertyKey(t),t);for(const [key,t] of [...unique].sort((a,b)=>a[1].name.localeCompare(b[1].name,'ko')||a[1].address.localeCompare(b[1].address,'ko'))){const o=el('option','',t.name+' · '+t.address);o.value=key;select.append(o);}if(unique.has(old))select.value=old;populateCaseTypes();clearCase();}
function populateCaseTypes(){const key=$('#caseProperty').value,select=$('#caseType');select.replaceChildren();const all=el('option','','전체 타입');all.value='';select.append(all);const types=[...new Set((state.result?.included||[]).filter(t=>E.propertyKey(t)===key).map(t=>t.type))].sort((a,b)=>a-b);for(const type of types){const o=el('option','',type+'타입');o.value=String(type);select.append(o);}}
function clearCase(){state.caseResult=null;state.selected.cases=new Set();$('#chart').replaceChildren();$('#chartTooltip').hidden=true;$('#caseNote').textContent='상단 필터·계약기간을 적용합니다. 단지와 집계 기준을 선택하고 분석을 누르세요. 전체 타입은 면적 구성 변화에 영향을 받습니다.';if(state.tab==='cases')renderTable();}
function analyzeCase(){if(!state.result||!$('#caseProperty').value){notify('선택 조건에 분석할 단지가 없습니다.',true);return;}state.caseResult=E.trend(state.filtered,$('#caseProperty').value,$('#caseType').value||null,$('#caseFrequency').value);state.selected.cases=new Set();const result=state.caseResult;$('#caseNote').textContent=`${$('#caseType').selectedOptions[0].textContent} · 개별 거래 ${nf.format(result.trades.length)}건 · 그래프 날짜 미확인 ${result.missing}건 제외 · ${state.filters.from?state.filters.from+' ~ '+state.filters.to:'원본 전체 기간'}`;renderChart(result.points);renderTable();}
function renderChart(points){const container=$('#chart');container.replaceChildren();if(!points.length){container.append(el('p','hint','날짜가 확인되는 거래가 없어 그래프를 그릴 수 없습니다.'));return;}const NS='http://www.w3.org/2000/svg',svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 1100 250');svg.setAttribute('role','img');svg.setAttribute('aria-label','기간별 평균 평당가 그래프. 각 점을 선택하면 가격과 거래 건수가 표시됩니다.');const make=(tag,attrs,text)=>{const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!=null)n.textContent=text;svg.append(n);return n;};const values=points.map(p=>p.average);let lo=Math.min(...values),hi=Math.max(...values);const pad=Math.max((hi-lo)*.18,1);lo=Math.max(0,lo-pad);hi+=pad;const date=p=>Date.parse(p.date+(p.date.length===7?'-01':'')+'T00:00:00Z'),min=date(points[0]),span=Math.max(1,date(points.at(-1))-min);const xy=p=>[points.length===1?570:85+(date(p)-min)/span*965,205-(p.average-lo)/(hi-lo)*180];for(let i=0;i<4;i++){const y=25+i*60;make('line',{x1:85,x2:1050,y1:y,y2:y,class:'chart-grid'});make('text',{x:73,y:y+5,'text-anchor':'end',class:'chart-label'},nf.format(hi-(hi-lo)*i/3));}make('polyline',{points:points.map(p=>xy(p).join(',')).join(' '),class:'chart-line'});for(const i of [...new Set([0,Math.floor(points.length/2),points.length-1])]){make('text',{x:xy(points[i])[0],y:234,'text-anchor':'middle',class:'chart-label'},points[i].date);}for(const p of points){const[x,y]=xy(p),text=`${p.date}\n평균 평당가: ${nf.format(p.average)} 만원/평\n거래 건수: ${p.count}건`;const dot=make('circle',{cx:x,cy:y,r:5,class:'chart-point',tabindex:0,'aria-label':text});const title=document.createElementNS(NS,'title');title.textContent=text;dot.append(title);const show=e=>{const tip=$('#chartTooltip');tip.textContent=text;tip.hidden=false;const rect=dot.getBoundingClientRect(),mx=e.clientX??rect.x,my=e.clientY??rect.y;tip.style.left=Math.max(8,Math.min(innerWidth-260,mx+14))+'px';tip.style.top=Math.max(8,my-88)+'px';};dot.addEventListener('pointerenter',show);dot.addEventListener('pointermove',show);dot.addEventListener('focus',show);dot.addEventListener('pointerleave',()=>$('#chartTooltip').hidden=true);dot.addEventListener('blur',()=>$('#chartTooltip').hidden=true);}container.append(svg,el('p','chart-description','거래가 없는 기간은 생략합니다. 점 사이의 선은 참고용입니다. 전체 타입을 비교할 때 면적 구성 변화에 유의하세요.'));}
const escapeHTML=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const tsv=v=>{let s=String(v??'');if(typeof v!=='number'&&/^[\s]*[=+\-@]/.test(s))s="'"+s;return /[\t\n\r"]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s;};
export function copyPayload(rows,columns,withHeaders){const values=rows.map(r=>columns.map(c=>{const v=c.value(r);return c.roundCopy&&typeof v==='number'?Math.round(v):v;}));const labels=columns.map(c=>c.exportLabel||c.label),all=withHeaders?[labels,...values]:values;const text=all.map(row=>row.map(tsv).join('\t')).join('\r\n');const html='<html xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="utf-8"></head><body><table border="1" cellspacing="0" cellpadding="5" style="border-collapse:collapse;font-family:Malgun Gothic,Arial;font-size:11pt">'+all.map((row,i)=>'<tr>'+row.map(v=>{const numeric=typeof v==='number',tag=withHeaders&&i===0?'th':'td';return `<${tag} ${numeric?'x:num="'+escapeHTML(v)+'"':'x:str="'+escapeHTML(v)+'"'} style="border:1px solid #bac5d1;text-align:${numeric?'right':'left'};mso-number-format:${numeric?'\'#,##0\'':'\'\\@\''}">${escapeHTML(numeric?nf.format(v):v)}</${tag}>`;}).join('')+'</tr>').join('')+'</table></body></html>';return {text,html};}
async function writeClipboard(payload){try{if(navigator.clipboard?.write&&globalThis.ClipboardItem){await navigator.clipboard.write([new ClipboardItem({'text/plain':new Blob([payload.text],{type:'text/plain'}),'text/html':new Blob([payload.html],{type:'text/html'})})]);return true;}throw Error('fallback');}catch{let copied=false;const listener=e=>{e.preventDefault();e.clipboardData.setData('text/plain',payload.text);e.clipboardData.setData('text/html',payload.html);copied=true;};document.addEventListener('copy',listener,{once:true});try{copied=document.execCommand('copy')&&copied;}catch{}document.removeEventListener('copy',listener);if(copied)return true;$('#copyFallback textarea').value=payload.text;$('#copyFallback').showModal();$('#copyFallback textarea').select();return false;}}
async function copyRows(all){if(!state.source)return;const visible=currentRows(),rows=all?visible:visible.filter(r=>selectedSet().has(r.id));if(!rows.length){notify('복사할 행의 체크박스를 먼저 선택해 주세요.',true);return;}const success=await writeClipboard(copyPayload(rows,currentColumns(),$('#includeHeaders').checked));if(success)notify(`${nf.format(rows.length)}행을 표로 복사했습니다. Excel·PowerPoint에서 붙여넣으세요.`);}
$('#copySelected').addEventListener('click',()=>copyRows(false));$('#copyAll').addEventListener('click',()=>copyRows(true));$('#closeCopy').addEventListener('click',()=>$('#copyFallback').close());
$('.table-frame').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='c'&&!['INPUT','TEXTAREA'].includes(e.target.tagName)&&!window.getSelection()?.toString()){e.preventDefault();copyRows(false);}});
$('#copySource').addEventListener('click',async()=>{if(!state.source)return;const text=E.sourceText(state.source);if(await writeClipboard({text,html:'<div>'+text.split('\n').map(escapeHTML).join('<br>')+'</div>'}))notify('출처·기준을 복사했습니다.');});
$('#export').addEventListener('click',async()=>{if(!state.source||state.busy)return;busy(true);notify('전체 결과를 엑셀로 저장하는 중…');try{const blob=await exportXlsx(state.source,state.all,COLUMNS);const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='평당가분석_'+state.source.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);notify('필터·검색과 관계없이 전체 결과 3개 시트를 저장했습니다.');}catch(err){notify('저장하지 못했습니다: '+err.message,true);}finally{busy(false);}});
$('#openFile').addEventListener('click',()=>$('#file').click());$('#emptyOpen').addEventListener('click',()=>$('#file').click());$('#file').addEventListener('change',e=>loadFile(e.target.files[0]));
let dragCount=0;document.addEventListener('dragenter',e=>{if([...e.dataTransfer.types].includes('Files')){e.preventDefault();dragCount++;document.body.classList.add('dragover');}});document.addEventListener('dragover',e=>{if([...e.dataTransfer.types].includes('Files'))e.preventDefault();});document.addEventListener('dragleave',()=>{if(--dragCount<=0){dragCount=0;document.body.classList.remove('dragover');}});document.addEventListener('drop',e=>{if(!e.dataTransfer.files.length)return;e.preventDefault();dragCount=0;document.body.classList.remove('dragover');if(e.dataTransfer.files.length!==1){notify('한 번에 엑셀 파일 하나를 넣어 주세요.',true);return;}loadFile(e.dataTransfer.files[0]);});
$('#applyDates').addEventListener('click',()=>{const from=$('#from').value,to=$('#to').value;if(!from||!to||from>to){notify('시작일과 종료일을 확인해 주세요.',true);return;}state.filters.from=from;state.filters.to=to;applyFilters();notify('계약기간을 적용했습니다.');});$('#resetDates').addEventListener('click',()=>{state.filters.from=state.filters.to=null;setDateInputs();applyFilters();notify('다른 필터를 유지하고 전체 기간으로 되돌렸습니다.');});$('#resetFilters').addEventListener('click',resetAll);let searchTimer;$('#search').addEventListener('input',e=>{clearTimeout(searchTimer);const value=e.target.value;searchTimer=setTimeout(()=>{state.query=value.trim();renderTable();},120);});
$('#caseProperty').addEventListener('change',()=>{populateCaseTypes();clearCase();});$('#caseType').addEventListener('change',clearCase);$('#caseFrequency').addEventListener('change',clearCase);$('#analyzeCase').addEventListener('click',analyzeCase);
renderFilters();
