if(document.modelContext?.registerTool){for(const tool of [{name:'read_analysis_summary',title:'현재 분석 요약',description:'현재 브라우저에서 열린 매매 자료의 분석 건수와 적용 계약기간을 읽습니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('입력 항목이 없어야 합니다.');return state.result?{file:state.source.name,included:state.result.included.length,excluded:state.result.excluded.length,groups:state.result.apartments.length,from:state.filters.from,to:state.filters.to}:{loaded:false};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}
